import json
import os
import requests
jsonFile = open (r"C:\Users\david\Downloads\general-01_2022_06_20.json\general-01_2022_06_20.json", 'r')
f =  jsonFile.read()   # 要先使用 read 讀取檔案
parsed_data = json.loads(f)      # 再使用 loads
#file = json.load(f)
# Check the type of the parsed data
if isinstance(parsed_data, dict):
    print("The JSON data represents a dictionary.")
elif isinstance(parsed_data, list):
    print("The JSON data represents a list.")
else:
    print("The JSON data has an unexpected structure.")
# Specify the path for the text file
#txt_file_path = 'detectAI\output.txt'

# Save the JSON data to a text file
#with open(txt_file_path, 'w') as txt_file:
#    json.dump(parsed_data, txt_file)

#print(f'The JSON data has been saved to {txt_file_path}')
def download_file(url, destination):
    response = requests.get(url)
    with open(destination, 'wb') as file:
        file.write(response.content)

for i in range(10):
    url = parsed_data["messages"][i][0]["attachments"][0]["url"]
    print(url)

    folder = 'detectAI\discord_pictures'
    file_name = f'downloaded_image.png{i}'
    destination = os.path.join(folder, file_name)

    # Create the 'pictures' folder if it doesn't exist
    os.makedirs(folder, exist_ok=True)

    download_file(url, destination)
    print(f'The file has been downloaded and saved to {destination}')

